/** Based on the ../anvil extension. */
import { ParamDefinition as PD } from '../../mol-util/param-definition.js';
import { Representation } from '../../mol-repr/representation.js';
import { StructureRepresentationStateBuilder } from '../../mol-repr/structure/representation.js';
// TODO: Convert this approach to a more usual one that creates visuals during parse and shows them
// during visuals.
const KinemageDataVisuals = {};
export const KinemageDataParams = {
    visuals: PD.MultiSelect([], PD.objectToOptions(KinemageDataVisuals)),
};
export function getKinemageDataParams(ctx, structure) {
    return PD.clone(KinemageDataParams);
}
export function KinemageDataRepresentation(ctx, getParams) {
    return Representation.createMulti('Membrane Orientation', ctx, getParams, StructureRepresentationStateBuilder, KinemageDataVisuals);
}
